script:
(function () {
  'use strict';
  // Currency conversion. Reference rates are the European Central Bank's daily euro reference
  // rates, fetched from the free, keyless Frankfurter API (api.frankfurter.dev, CORS-enabled).
  // ECB quotes every currency per 1 EUR, so a cross rate is
  //   1 FROM = rate[TO] / rate[FROM] TO      (rate[EUR] = 1)
  // and converted amount = amount x rate. A rate typed by the user always overrides the reference
  // rate, so the calculator works offline. The last good download is kept in localStorage and
  // used (with its date) if a later request fails.
  // This is the only tool on the site that makes a network request.
  // Endpoint checked October 1, 2026: v2 /rates (ECB provider) and the deprecated v1 /latest
  // fallback both return Access-Control-Allow-Origin: *. Verified (Node scratch test with the
  // live September 30, 2026 ECB response): USD->EUR 0.880669 and USD->GBP 0.752646 match the
  // API's own base=USD values (0.88067, 0.75265); GBP->JPY 208.593. Tested: v2 failure falls back
  // to v1, both failing uses the saved copy, no saved copy + no manual rate shows a prompt (no
  // NaN), manual rate overrides and is compared with the reference rate, swap inverts it.
  var SOURCES = [
    { url: 'https://api.frankfurter.dev/v2/rates?base=EUR&providers=ECB', parse: parseV2 },
    { url: 'https://api.frankfurter.dev/v1/latest', parse: parseV1 }
  ];
  var STORE_KEY = 'cmc-currency-ecb-rates';
  var MAJORS = ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD', 'CHF', 'CNY', 'MXN', 'INR'];
  var AMOUNTS = [1, 5, 10, 20, 50, 100, 500, 1000, 5000];
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September',
                'October', 'November', 'December'];
  var rateFmt = new Intl.NumberFormat('en-US', { maximumSignificantDigits: 6 });
  var pctFmt = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  var loading = false;
  var ref = null; // { rates: {CODE: per-EUR rate}, date: 'YYYY-MM-DD', saved: bool }

  function parseV2(data) {
    if (!Array.isArray(data)) return null;
    var rates = { EUR: 1 }, date = '', count = 0;
    data.forEach(function (row) {
      if (row && typeof row.quote === 'string' && typeof row.rate === 'number' && isFinite(row.rate) && row.rate > 0) {
        rates[row.quote.toUpperCase()] = row.rate;
        count++;
        if (typeof row.date === 'string' && row.date > date) date = row.date;
      }
    });
    return count ? { rates: rates, date: date } : null;
  }

  function parseV1(data) {
    if (!data || typeof data.rates !== 'object' || data.rates === null) return null;
    var rates = { EUR: 1 }, count = 0;
    Object.keys(data.rates).forEach(function (code) {
      var r = data.rates[code];
      if (typeof r === 'number' && isFinite(r) && r > 0) { rates[code.toUpperCase()] = r; count++; }
    });
    return count ? { rates: rates, date: typeof data.date === 'string' ? data.date : '' } : null;
  }

  function crossRate(rates, from, to) {
    if (from === to) return 1;
    if (!rates || !(rates[from] > 0) || !(rates[to] > 0)) return null;
    return rates[to] / rates[from];
  }

  function longDate(iso) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || '');
    if (!m) return 'an unknown date';
    return MONTHS[parseInt(m[2], 10) - 1] + ' ' + parseInt(m[3], 10) + ', ' + m[1];
  }

  function formatMoney(value, code) {
    try {
      return new Intl.NumberFormat('en-US', { style: 'currency', currency: code }).format(value);
    } catch (e) {
      return rateFmt.format(value) + ' ' + code;
    }
  }

  function num(id) {
    var raw = document.getElementById(id).value;
    if (raw === '') return null;
    var v = parseFloat(raw);
    return isNaN(v) ? NaN : v;
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function readStore() {
    try {
      var d = JSON.parse(window.localStorage.getItem(STORE_KEY) || 'null');
      if (d && d.rates && typeof d.rates === 'object' && typeof d.date === 'string') return d;
    } catch (e) { /* storage blocked or bad data */ }
    return null;
  }

  function writeStore(d) {
    try { window.localStorage.setItem(STORE_KEY, JSON.stringify({ rates: d.rates, date: d.date })); } catch (e) { /* ignore */ }
  }

  function fetchJSON(url) {
    var ctrl = typeof AbortController === 'function' ? new AbortController() : null;
    var timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 8000) : null;
    return fetch(url, ctrl ? { signal: ctrl.signal } : {}).then(function (res) {
      if (timer) clearTimeout(timer);
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    }, function (err) {
      if (timer) clearTimeout(timer);
      throw err;
    });
  }

  function tryFrom(index) {
    if (index >= SOURCES.length) return Promise.reject(new Error('no source'));
    var src = SOURCES[index];
    return fetchJSON(src.url).then(function (data) {
      var d = src.parse(data);
      if (!d) throw new Error('bad data');
      return d;
    }).catch(function () { return tryFrom(index + 1); });
  }

  function setStatus(text, state) {
    var el = document.getElementById('cxStatus');
    el.textContent = text;
    el.setAttribute('data-state', state);
  }

  function loadRates() {
    if (typeof fetch !== 'function' || typeof Promise !== 'function') {
      useSaved('Your browser can\'t download reference rates.');
      return;
    }
    setStatus('Loading the latest ECB reference rates…', 'loading');
    loading = true;
    tryFrom(0).then(function (d) {
      loading = false;
      ref = { rates: d.rates, date: d.date, saved: false };
      writeStore(d);
      setStatus('ECB reference rates for ' + longDate(d.date) + '.', 'live');
      update();
    }).catch(function () {
      loading = false;
      useSaved('Couldn\'t load the latest reference rates.');
    });
  }

  function useSaved(prefix) {
    var d = readStore();
    if (d) {
      ref = { rates: d.rates, date: d.date, saved: true };
      setStatus(prefix + ' Showing the last rates saved in this browser, from ' + longDate(d.date) + '.', 'saved');
    } else {
      setStatus(prefix + ' Type your own exchange rate below to convert.', 'error');
    }
    update();
  }

  function clear(body) { while (body.firstChild) body.removeChild(body.firstChild); }

  function row(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function update() {
    var from = document.getElementById('cxFrom').value, to = document.getElementById('cxTo').value;
    var amount = num('cxAmount'), manual = num('cxManual');
    set('cxManualFrom', '1 ' + from + ' =');
    set('cxManualTo', to);
    var refRate = ref ? crossRate(ref.rates, from, to) : null;
    var error = document.getElementById('cxError');
    var msg = '';
    if (amount === null || isNaN(amount) || amount < 0) msg = 'Enter an amount of 0 or more.';
    else if (manual !== null && (isNaN(manual) || manual <= 0)) msg = 'Your exchange rate must be a number above 0, or leave it blank.';
    else if (manual === null && refRate === null && !loading) {
      msg = ref ? 'No reference rate is available for this pair. Type your own exchange rate to convert.'
                : 'Reference rates couldn\'t be loaded. Type your own exchange rate to convert.';
    }
    error.hidden = !msg;
    error.textContent = msg;

    var refText = refRate === null ? 'Not available' : '1 ' + from + ' = ' + rateFmt.format(refRate) + ' ' + to;
    set('cxRefRate', refText);
    var majors = document.getElementById('cxMajors');
    clear(majors);
    MAJORS.forEach(function (code) {
      if (code === from) return;
      var r = ref ? crossRate(ref.rates, from, code) : null;
      row(majors, [code, r === null ? 'n/a' : rateFmt.format(r), r === null ? 'n/a' : rateFmt.format(1 / r)]);
    });
    set('cxMajorsFrom', from);
    set('cxMajorsFrom2', from);

    var amounts = document.getElementById('cxAmounts');
    var waiting = !msg && manual === null && refRate === null;
    if (msg || waiting) {
      set('cxResultFrom', waiting ? 'Waiting for reference rates…' : 'Converted amount');
      ['cxResult', 'cxRateUsed', 'cxInverse', 'cxRateSource', 'cxCompare'].forEach(function (id) { set(id, '–'); });
      clear(amounts);
      return;
    }
    var rate = manual !== null ? manual : refRate;
    set('cxResult', formatMoney(amount * rate, to));
    set('cxResultFrom', formatMoney(amount, from) + ' =');
    set('cxRateUsed', '1 ' + from + ' = ' + rateFmt.format(rate) + ' ' + to);
    set('cxInverse', '1 ' + to + ' = ' + rateFmt.format(1 / rate) + ' ' + from);
    set('cxRateSource', manual !== null ? 'Your own rate' :
      (from === to ? 'Same currency' : 'ECB reference rate, ' + longDate(ref.date) + (ref.saved ? ' (saved copy)' : '')));
    if (manual !== null && refRate !== null && from !== to) {
      var diff = (manual / refRate - 1) * 100;
      var gap = amount * (refRate - manual);
      set('cxCompare', Math.abs(diff) < 0.005 ? 'Same as the reference rate' :
        pctFmt.format(Math.abs(diff)) + '% ' + (diff < 0 ? 'worse' : 'better') + ' (' +
        formatMoney(Math.abs(gap), to) + (diff < 0 ? ' less' : ' more') + ')');
    } else {
      set('cxCompare', manual !== null ? 'No reference rate to compare' : 'No rate entered');
    }
    clear(amounts);
    AMOUNTS.forEach(function (a) { row(amounts, [formatMoney(a, from), formatMoney(a * rate, to)]); });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cxForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('cxSwap').addEventListener('click', function () {
      var f = document.getElementById('cxFrom'), t = document.getElementById('cxTo'), tmp = f.value;
      f.value = t.value;
      t.value = tmp;
      var m = document.getElementById('cxManual');
      var mv = parseFloat(m.value);
      if (m.value !== '' && mv > 0) m.value = String(parseFloat((1 / mv).toPrecision(6)));
      update();
    });
    loadRates();
    update();
  });
})();
